// --- MENU ---
const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const allDishes = categories.flatMap(c => c.dishes || []);
  const filteredDishes = allDishes.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <PageLayout title="Menu">
      <div className="max-w-md mx-auto mb-16 text-center">
        <input type="text" placeholder="RECHERCHER UN PLAT..." className="w-full bg-white/5 border border-white/10 rounded-full py-5 px-10 text-white outline-none focus:border-orange-600 transition font-black italic uppercase text-xs tracking-widest backdrop-blur-xl text-center" onChange={(e) => setSearchTerm(e.target.value)} />
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredDishes.map(item => (
          <div key={item.id} className="bg-black/40 backdrop-blur-lg border border-white/10 rounded-[3rem] overflow-hidden group shadow-2xl">
            <div className="h-64 overflow-hidden relative">
              <img src={item.image || "https://images.unsplash.com/photo-1513104890138-7c749659a591"} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-700" />
            </div>
            <div className="p-8 text-center">
              <h3 className="text-2xl font-black text-white italic mb-2 uppercase">{item.name}</h3>
              <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
              <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 hover:text-white transition">Commander</button>
            </div>
          </div>
        ))}
      </div>
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md p-4">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center shadow-2xl">
            <h3 className="text-2xl font-black text-gray-900 italic uppercase mb-2">Mode</h3>
            <div className="space-y-4">
              <button onClick={() => { addToCart({...selectedItem, type: 'Sur Place'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-100 hover:bg-orange-600 hover:text-white text-gray-900 rounded-2xl font-black uppercase tracking-widest transition-all">🍽️ Sur Place</button>
